script:
(function () {
  'use strict';
  // Real after-tax return on savings whose earnings are taxed every year (bank interest, CDs,
  // bond funds held in a taxable account).
  //   After-tax return  ra = r x (1 - (federal + state rate))
  //   Real after-tax return  = (1 + ra) / (1 + i) - 1      (exact Fisher relation, not ra - i)
  //   Break-even return (keeps pace with inflation after tax) = i / (1 - tax rate)
  // Balances grow monthly at (1 + rate)^(1/12) - 1 with deposits at the end of each month, for three
  // cases: no tax, after tax, and after tax in today's dollars (divided by (1 + i)^years). The
  // optional raise grows the monthly deposit by the inflation rate at the start of each year.
  // Split of the gross growth: "lost to tax" = untaxed balance - after-tax balance; "lost to
  // inflation" = after-tax balance - its value in today's dollars.
  // Verified (Node scratch test, tests/st.test.js):
  //   $10,000, 5%, 22% + 5% tax, 3% inflation, 10 years, no deposits: after-tax rate 3.65%,
  //     balance 10,000 x 1.0365^10 = $14,311.76; today's dollars 14,311.76 / 1.03^10 = $10,649.29;
  //     real after-tax return 1.0365 / 1.03 - 1 = 0.631%; break-even 3% / 0.73 = 4.110%.
  //   0% return and 0% inflation: balances equal the deposits, no NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x) { return (x * 100).toFixed(2) + '%'; }

  function project(o) {
    var ra = o.r * (1 - o.tax);
    var gGross = Math.pow(1 + o.r, 1 / 12) - 1, gNet = Math.pow(1 + ra, 1 / 12) - 1;
    var gross = o.start, net = o.start, deposits = o.start, dep = o.monthly, rows = [];
    for (var y = 1; y <= o.years; y++) {
      if (y > 1 && o.raise) dep *= 1 + o.i;
      for (var m = 1; m <= 12; m++) {
        gross = gross * (1 + gGross) + dep;
        net = net * (1 + gNet) + dep;
        deposits += dep;
      }
      var real = net / Math.pow(1 + o.i, y);
      rows.push({ year: y, deposits: deposits, gross: gross, net: net, real: real });
    }
    return { ra: ra, gross: gross, net: net, deposits: deposits, real: net / Math.pow(1 + o.i, o.years), rows: rows };
  }

  function clearRows(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function update() {
    var o = {
      start: num('stStart'), monthly: num('stMonthly'), years: Math.round(num('stYears')), r: num('stReturn') / 100,
      fed: num('stFed') / 100, state: num('stState') / 100, i: num('stInflation') / 100,
      raise: document.getElementById('stRaise').checked
    };
    var error = document.getElementById('stError');
    var msg = '';
    if ([o.start, o.monthly, o.years, o.r, o.fed, o.state, o.i].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.start < 0 || o.monthly < 0) msg = 'Amounts cannot be negative.';
    else if (o.years < 1 || o.years > 60) msg = 'Enter 1 to 60 years.';
    else if (o.r < 0 || o.r > 0.3) msg = 'Enter a rate of return from 0 to 30%.';
    else if (o.fed < 0 || o.fed > 0.5 || o.state < 0 || o.state > 0.2) msg = 'Enter a federal rate from 0 to 50% and a state rate from 0 to 20%.';
    else if (o.i < -0.05 || o.i > 0.2) msg = 'Enter an inflation rate from -5% to 20%.';
    error.hidden = !msg;
    error.textContent = msg;
    var ids = ['stRealRate', 'stReal', 'stNet', 'stGross', 'stDeposits', 'stLostTax', 'stLostInfl', 'stAfterTaxRate', 'stBreakEven'];
    if (msg) {
      ids.forEach(function (id) { set(id, '–'); });
      document.getElementById('stNote').hidden = true;
      clearRows('stSchedule');
      return;
    }
    o.tax = o.fed + o.state;
    var p = project(o);
    var realRate = (1 + p.ra) / (1 + o.i) - 1;
    var breakEven = o.tax < 1 ? o.i / (1 - o.tax) : NaN;
    set('stRealRate', pct(realRate));
    set('stReal', money.format(p.real));
    set('stNet', money.format(p.net));
    set('stGross', money.format(p.gross));
    set('stDeposits', money.format(p.deposits));
    set('stLostTax', money.format(p.gross - p.net));
    set('stLostInfl', money.format(p.net - p.real));
    set('stAfterTaxRate', pct(p.ra));
    set('stBreakEven', isFinite(breakEven) && breakEven >= 0 ? pct(breakEven) : 'Not needed');
    var note = document.getElementById('stNote');
    note.hidden = false;
    if (realRate < -0.00005) note.textContent = 'After tax and inflation your savings lose ' + pct(-realRate) +
      ' of buying power a year. You would need to earn at least ' + pct(breakEven) + ' before tax just to stand still.';
    else if (realRate < 0.00005) note.textContent = 'After tax and inflation your savings just about hold their buying power.';
    else note.textContent = 'After tax and inflation your savings grow their buying power by ' + pct(realRate) + ' a year.';
    var body = clearRows('stSchedule');
    p.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.year), money.format(row.deposits), money.format(row.gross), money.format(row.net), money.format(row.real)].forEach(function (t) {
        var td = document.createElement('td');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('stForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
